(181817, 10393, 5515, '<td valign="top">Great thought. Good concept...</td>', 'Great thought. Good concept...', '2003-01-03 11:49:23.000000', NULL, 1),
(181818, 10386, 5515, '<td valign="top">Good shot. Great comp. Nice DOF. Really need to see the bottom of the lobster tail though. It is creating an un easy pressure point. My eye goes to it and not the center of the image...</td>', 'Good shot. Great comp. Nice DOF. Really need to see the bottom of the lobster tail though. It is creating an un easy pressure point. My eye goes to it and not the center of the image...', '2003-01-03 11:50:26.000000', NULL, 1),
(181820, 10412, 5515, '<td valign="top">Nice shot. Like the effect. Great timing and exposure.</td>', 'Nice shot. Like the effect. Great timing and exposure.', '2003-01-03 11:51:12.000000', NULL, 1),
(181821, 10408, 5515, '<td valign="top">Nice DOF, not an easy shot to obtain. Great stuff...</td>', 'Nice DOF, not an easy shot to obtain. Great stuff...', '2003-01-03 11:51:47.000000', NULL, 1),
(181823, 10388, 5515, '<td valign="top">Nicely captured B+W. Excellent stuff...<br/> <br/>Dave</td>', 'Nicely captured B+W. Excellent stuff... Dave', '2003-01-03 11:52:18.000000', NULL, 1),
(181825, 10419, 5515, '<td valign="top">I like it. Would have liked to see her looking into the camera though. Also a little more light on the subject and a little less in the BG... Great thought...</td>', 'I like it. Would have liked to see her looking into the camera though. Also a little more light on the subject and a little less in the BG... Great thought...', '2003-01-03 11:53:18.000000', NULL, 1),
(181826, 10357, 5515, '<td valign="top">Great shot. Possibly: a direct diagonal from corner to corner? And a little more light on the subject to create more fall off between it and the background...<br/> <br/>Dave</td>', 'Great shot. Possibly: a direct diagonal from corner to corner? And a little more light on the subject to create more fall off between it and the background... Dave', '2003-01-03 11:54:25.000000', NULL, 1),
(181831, 10387, 5515, '<td valign="top">Looks a little soft to me. Also when shooting hands make sure the hands are clean expecially in a shot like this. I like the flame in the BG. Nice timing. Reflections are also at a minimum, well done.</td>', 'Looks a little soft to me. Also when shooting hands make sure the hands are clean expecially in a shot like this. I like the flame in the BG. Nice timing. Reflections are also at a minimum, well done.', '2003-01-03 11:57:44.000000', NULL, 1),
(181832, 10353, 5515, '<td valign="top">Fine detail. Excellent job...</td>', 'Fine detail. Excellent job...', '2003-01-03 11:58:10.000000', NULL, 1),
(181833, 10439, 5515, '<td valign="top">Just great.... One of my favorites....</td>', 'Just great.... One of my favorites....', '2003-01-03 11:58:30.000000', NULL, 1),
(181834, 10436, 5515, '<td valign="top">This doesn''t scream "New Years" to me but it is an exceptional image. I love the lighting. I notice a strange reflection on the front facade (dark greenish area) by the point abovce the round window. Sort of a yellowish reflection? Real annoying and my eye goes right to it now that I noticed it. Easy enought to remove. Is it a reflection?</td>', 'This doesn''t scream "New Years" to me but it is an exceptional image. I love the lighting. I notice a strange reflection on the front facade (dark greenish area) by the point abovce the round window. Sort of a yellowish reflection? Real annoying and my eye goes right to it now that I noticed it. Easy enought to remove. Is it a reflection?', '2003-01-03 12:01:05.000000', NULL, 1),
(181835, 10420, 5515, '<td valign="top">Nice Candid!!!</td>', 'Nice Candid!!!', '2003-01-03 12:01:22.000000', NULL, 1),
(181836, 10375, 5515, '<td valign="top">Nice image. Would have liked to see the shadows in the ashtray opened a little more to give more of a hint as to it''s presense. That is a small nitpic though...<br/> <br/></td>', 'Nice image. Would have liked to see the shadows in the ashtray opened a little more to give more of a hint as to it''s presense. That is a small nitpic though... ', '2003-01-03 12:02:18.000000', NULL, 1),
(181838, 10426, 5515, '<td valign="top">The foreground is screaming to be in focus on this one. My eye keeps trying to focus in on it. Does make me hungry though...</td>', 'The foreground is screaming to be in focus on this one. My eye keeps trying to focus in on it. Does make me hungry though...', '2003-01-03 12:03:07.000000', NULL, 1),
(181839, 10394, 5515, '<td valign="top">Did you go in my trash??? LOL Nice image...</td>', 'Did you go in my trash??? LOL Nice image...', '2003-01-03 12:03:45.000000', NULL, 1),
(181929, 10403, 4085, '<td valign="top">A bit OOF on this pic.  Being a parent myself, I''m not too crazy about the content.</td>', 'A bit OOF on this pic.  Being a parent myself, I''m not too crazy about the content.', '2003-01-03 14:34:28.000000', NULL, 1),
