(186853, 10416, 3575, '<td valign="top">Congratulations on 3rd place and congratulations for quitting the smoking habit. I don''t know how you could have photographed this without wanting to smoke it!</td>', 'Congratulations on 3rd place and congratulations for quitting the smoking habit. I don''t know how you could have photographed this without wanting to smoke it!', '2003-01-10 11:12:36.000000', NULL, 0),
(186858, 10416, 210, '<td valign="top">I haven''t posted in ages, but when I saw this, I had to say: Amazing.  I love this.  You know, I bet tons of people (advertising?  thetruth?) would love to buy this picture.</td>', 'I haven''t posted in ages, but when I saw this, I had to say: Amazing.  I love this.  You know, I bet tons of people (advertising?  thetruth?) would love to buy this picture.', '2003-01-10 11:36:18.000000', NULL, 0),
